// replaceFirstPair replaces the first occurrence of open with openTag and
// the following first occurrence of close with closeTag.
func replaceFirstPair(s, delimiter, openTag, closeTag string) string {
	open := strings.Index(s, delimiter)
	if open < 0 {
		return s
	}
	close := strings.Index(s[open+len(delimiter):], delimiter)
	if close < 0 {
		return s
	}
	close += open + len(delimiter)
